export const makeInventoryPreCommitCompensationService = (dependencies: {
  readonly cleanup: InventoryPreCommitCleanupPort;
  readonly createEffects: CreateEffectPersistence;
  readonly ledger: InventoryEffectLedgerService;
  readonly makeReleaseEffectId: (
    createEffectId: CompensateInventoryPreCommitPayload['createEffectId'],
  ) => typeof ReservationReleaseEffectIdSchema.Type;
  readonly orderTruth: InventoryPreCommitOrderTruthPort;
  readonly release: InventoryReservationReleaseService;
}): InventoryPreCommitCompensationService => ({
  compensate: Effect.fn('InventoryPreCommitCompensation.compensate')(
    function* compensate(
      payload,
      context,
    ): Effect.fn.Return<InventoryPreCommitCompensationDecision, CompensateInventoryPreCommitError> {
      const current = yield* readExactEffect(dependencies.createEffects, payload);
      if (
        current.request.authority.tenantId !== context.tenantId ||
        current.request.legalEntityId !== context.legalEntityId
      ) {
        return yield* rejected(payload.createEffectId, 'TENANT_SCOPE_MISMATCH');
      }
      if (!sameRef(current.request.reservation.ref, payload.authorizationTargetRef)) {
        return yield* rejected(payload.createEffectId, 'AUTHORIZATION_TARGET_MISMATCH');
      }
      if (current.request.reservation.origin.attemptId !== payload.attemptId) {
        return yield* rejected(payload.createEffectId, 'ATTEMPT_SCOPE_MISMATCH');
      }

      const orderTruth = yield* dependencies.orderTruth.read(current);
      if (!Schema.is(ReservationReleaseNotCommittedClosedTruthSchema)(orderTruth)) {
        return { releaseDispatchRequested: false, result: blockForOrderTruth(current, orderTruth) };
      }

      if (Schema.is(ResolvedNoReservationCreateEffectSchema)(current)) {
        return {
          releaseDispatchRequested: false,
          result: {
            effect: current,
            outcome: current.reason === 'PRE_COMMIT_COMPENSATED' ? 'ALREADY_COMPENSATED' : 'NO_COMPENSATION_REQUIRED',
            safelyReusable: true,
          },
        };
      }

      if (Schema.is(EstablishedReservationCreateEffectSchema)(current)) {
        const release = yield* dependencies.release
          .request(
            {
              attemptId: payload.attemptId,
              releaseEffectId: dependencies.makeReleaseEffectId(payload.createEffectId),
              reservationRef: current.reservation.ref,
              scope: { _tag: 'WHOLE_RESERVATION' },
            },
            context,
          )
          .pipe(
            Effect.mapError((cause) =>
              Schema.is(InventoryReservationReleaseRejected)(cause)
                ? rejected(payload.createEffectId, 'RELEASE_CONFLICT')
                : inventoryPreCommitCompensationUnavailable(
                    payload.createEffectId,
                    'Reservation Release is unavailable',
                    cause,
                  ),
            ),
          );
        return {
          releaseDispatchRequested: release.dispatchRequested,
          result: { createEffect: current, outcome: 'RESERVATION_RELEASE', release: release.result },
        };
      }

      const ledgerRecord = yield* dependencies.ledger
        .recover(
          context.tenantId,
          inventoryEffectLedgerId(payload.createEffectId),
          reservationCreateLedgerIntent(current),
        )
        .pipe(
          Effect.mapError((cause) =>
            inventoryPreCommitCompensationUnavailable(
              payload.createEffectId,
              'Inventory effect ledger is unavailable',
              cause,
            ),
          ),
        );
      const observation = yield* dependencies.cleanup.reconcile(current, orderTruth);
      if (observation.effectId !== payload.createEffectId) {
        return yield* rejected(payload.createEffectId, 'INVALID_CLEANUP_OBSERVATION');
      }
      if (!('authorityIssuer' in observation)) {
        return {
          releaseDispatchRequested: false,
          result: {
            effect: current,
            observedAt: observation.observedAt,
            outcome: 'RECONCILIATION_REQUIRED',
            reason: 'CLEANUP_OUTCOME_UNKNOWN',
            safelyReusable: false,
          },
        };
      }
      if (
        !issuerMatchesOriginalAuthority(current, observation.authorityIssuer) ||
        !cleanupScopeMatches(current, observation.cleanedAllocations)
      ) {
        return yield* rejected(payload.createEffectId, 'INVALID_CLEANUP_OBSERVATION');
      }

      const originalObservedAt = 'observedAt' in current ? { originalObservedAt: current.observedAt } : {};
      const originalOwnerEvidenceRef =
        'ownerEvidenceRef' in current ? { originalOwnerEvidenceRef: current.ownerEvidenceRef } : {};
      const saved = yield* dependencies.createEffects
        .save(current, {
          _tag: 'RESOLVED_NO_RESERVATION',
          effectAbsenceProven: true,
          observedAt: observation.cleanedAt,
          preCommitCompensation: {
            authorityIssuer: observation.authorityIssuer,
            cleanedAllocations: observation.cleanedAllocations,
            cleanedAt: observation.cleanedAt,
            cleanupEvidenceRef: observation.cleanupEvidenceRef,
            cleanupOutcome: observation._tag,
            originalEffectState: current._tag,
            ...originalObservedAt,
            ...originalOwnerEvidenceRef,
            orderProof: {
              _tag: 'NOT_COMMITTED_CLOSED',
              closureEvidenceRef: orderTruth.closureEvidenceRef,
              nonCommitEvidenceRef: orderTruth.nonCommitEvidenceRef,
              observedAt: orderTruth.observedAt,
            },
          },
          reason: 'PRE_COMMIT_COMPENSATED',
          request: current.request,
        })
        .pipe(
          Effect.mapError((cause) =>
            inventoryPreCommitCompensationUnavailable(
              payload.createEffectId,
              'Cleanup resolution is unavailable',
              cause,
            ),
          ),
        );
      if (
        !Schema.is(ResolvedNoReservationCreateEffectSchema)(saved) ||
        saved.reason !== 'PRE_COMMIT_COMPENSATED' ||
        saved.preCommitCompensation === undefined
      ) {
        return yield* rejected(payload.createEffectId, 'EFFECT_ID_CONFLICT');
      }
      const terminal = saved;
      yield* synchronizeInventoryEffectLedger(
        dependencies.ledger,
        ledgerRecord.record,
        reservationCreateLedgerResolution(terminal),
      ).pipe(
        Effect.mapError((cause) =>
          inventoryPreCommitCompensationUnavailable(
            payload.createEffectId,
            'Inventory effect ledger is unavailable',
            cause,
          ),
        ),
      );
      return {
        releaseDispatchRequested: false,
        result: { effect: terminal, outcome: 'CREATE_EFFECT_COMPENSATED', safelyReusable: true },
      };
    },
  ),
});
